// Node types and list helpers a list starter ships. The text is practice.js HELPERS (content.test.mjs keeps them equal).
const NOEDIT='The page uses these helpers to build and read the lists, so leave them as they are.';
const CPPH='#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\n';
const LH={
 js:'// '+NOEDIT+'\nfunction fromList(v){\n  let head=null;\n  for(let i=v.length-1;i>=0;i--){head={value:v[i],next:head}}\n  return head;\n}\n\nfunction toList(head){\n  const out=[];\n  let n=head;\n  while(n&&out.length<10000){out.push(n.value);n=n.next}\n  return out;\n}\n\n',
 py:'# '+NOEDIT+'\ndef from_list(v):\n    head = None\n    i = len(v) - 1\n    while i >= 0:\n        head = {"value": v[i], "next": head}\n        i = i - 1\n    return head\n\ndef to_list(head):\n    out = []\n    n = head\n    while n is not None and len(out) < 10000:\n        out.append(n["value"])\n        n = n["next"]\n    return out\n\n',
 cpp:CPPH+'// '+NOEDIT+'\n// A link (next) is an index into the nodes table.\nstruct Node { int value; int next; };\nstruct List { vector<Node> nodes; int head; };\n\nList fromList(vector<int> v) {\n    List l;\n    l.head = -1;\n    for (int i = 0; i < v.size(); i++) {\n        Node n;\n        n.value = v[i];\n        n.next = -1;\n        if (i + 1 < v.size()) { n.next = i + 1; }\n        l.nodes.push_back(n);\n    }\n    if (v.size() > 0) { l.head = 0; }\n    return l;\n}\n\nvector<int> toList(List l) {\n    vector<int> out;\n    int i = l.head;\n    int seen = 0;\n    while (i != -1 && seen < l.nodes.size()) {\n        out.push_back(l.nodes[i].value);\n        i = l.nodes[i].next;\n        seen++;\n    }\n    return out;\n}\n\n',
 rs:'// '+NOEDIT+'\n// A link (next) is an index into the nodes table.\nstruct Node { value: i32, next: Option<usize> }\nstruct List { nodes: Vec<Node>, head: Option<usize> }\n\nfn from_list(v: Vec<i32>) -> List {\n    let mut nodes: Vec<Node> = Vec::new();\n    for i in 0..v.len() {\n        let mut next: Option<usize> = None;\n        if i + 1 < v.len() { next = Some(i + 1); }\n        nodes.push(Node { value: v[i], next: next });\n    }\n    let mut head: Option<usize> = None;\n    if v.len() > 0 { head = Some(0); }\n    List { nodes: nodes, head: head }\n}\n\nfn to_list(l: &List) -> Vec<i32> {\n    let mut out: Vec<i32> = Vec::new();\n    let mut cur = l.head;\n    let mut seen = 0;\n    while let Some(i) = cur {\n        if seen >= l.nodes.len() { break; }\n        out.push(l.nodes[i].value);\n        cur = l.nodes[i].next;\n        seen += 1;\n    }\n    out\n}\n\n'};
const NOEDITT='The page uses these helpers to build and read the trees, so leave them as they are.';
const TH={
 js:'// '+NOEDITT+'\nfunction fromTree(v){\n  if(!v.length)return null;\n  const mk=x=>x===-1||x===undefined?null:{value:x,left:null,right:null};\n  const root=mk(v[0]);\n  const q=[root];\n  let h=0,i=1;\n  while(h<q.length&&i<v.length){\n    const n=q[h++];\n    n.left=mk(v[i++]);\n    n.right=mk(v[i++]);\n    if(n.left)q.push(n.left);\n    if(n.right)q.push(n.right);\n  }\n  return root;\n}\n\nfunction toTree(root){\n  const out=[];\n  const q=[root];\n  let h=0,seen=0;\n  while(h<q.length&&seen<10000){\n    const n=q[h++];\n    if(!n){out.push(-1);continue}\n    seen++;\n    out.push(n.value);\n    q.push(n.left||null,n.right||null);\n  }\n  while(out.length&&out[out.length-1]===-1)out.pop();\n  return out;\n}\n\n',
 py:'# '+NOEDITT+'\ndef from_tree(v):\n    if len(v) == 0:\n        return None\n    root = {"value": v[0], "left": None, "right": None}\n    q = [root]\n    h = 0\n    i = 1\n    while h < len(q) and i < len(v):\n        n = q[h]\n        h = h + 1\n        if i < len(v) and v[i] != -1:\n            n["left"] = {"value": v[i], "left": None, "right": None}\n            q.append(n["left"])\n        i = i + 1\n        if i < len(v) and v[i] != -1:\n            n["right"] = {"value": v[i], "left": None, "right": None}\n            q.append(n["right"])\n        i = i + 1\n    return root\n\ndef to_tree(root):\n    out = []\n    q = [root]\n    h = 0\n    seen = 0\n    while h < len(q) and seen < 10000:\n        n = q[h]\n        h = h + 1\n        if n is None:\n            out.append(-1)\n        else:\n            seen = seen + 1\n            out.append(n["value"])\n            q.append(n["left"])\n            q.append(n["right"])\n    while len(out) > 0 and out[-1] == -1:\n        out.pop()\n    return out\n\n',
 cpp:CPPH+'// '+NOEDITT+'\n// A link (left, right) is an index into the nodes table.\nstruct Node { int value; int left; int right; };\nstruct Tree { vector<Node> nodes; int root; };\n\nTree fromTree(vector<int> v) {\n    Tree t;\n    t.root = -1;\n    if (v.size() == 0) { return t; }\n    Node r;\n    r.value = v[0];\n    r.left = -1;\n    r.right = -1;\n    t.nodes.push_back(r);\n    t.root = 0;\n    vector<int> q;\n    q.push_back(0);\n    int h = 0;\n    int i = 1;\n    while (h < q.size() && i < v.size()) {\n        int p = q[h];\n        h++;\n        for (int side = 0; side < 2; side++) {\n            if (i < v.size()) {\n                if (v[i] != -1) {\n                    Node c;\n                    c.value = v[i];\n                    c.left = -1;\n                    c.right = -1;\n                    t.nodes.push_back(c);\n                    int k = t.nodes.size() - 1;\n                    if (side == 0) { t.nodes[p].left = k; } else { t.nodes[p].right = k; }\n                    q.push_back(k);\n                }\n                i++;\n            }\n        }\n    }\n    return t;\n}\n\nvector<int> toTree(Tree t) {\n    vector<int> out;\n    vector<int> q;\n    q.push_back(t.root);\n    int h = 0;\n    int seen = 0;\n    while (h < q.size() && seen < t.nodes.size()) {\n        int i = q[h];\n        h++;\n        if (i == -1) {\n            out.push_back(-1);\n        } else {\n            seen++;\n            out.push_back(t.nodes[i].value);\n            q.push_back(t.nodes[i].left);\n            q.push_back(t.nodes[i].right);\n        }\n    }\n    while (out.size() > 0 && out[out.size() - 1] == -1) { out.pop_back(); }\n    return out;\n}\n\n',
 rs:'// '+NOEDITT+'\n// A link (left, right) is an index into the nodes table.\nstruct Node { value: i32, left: Option<usize>, right: Option<usize> }\nstruct Tree { nodes: Vec<Node>, root: Option<usize> }\n\nfn from_tree(v: Vec<i32>) -> Tree {\n    let mut nodes: Vec<Node> = Vec::new();\n    if v.len() == 0 { return Tree { nodes: nodes, root: None }; }\n    nodes.push(Node { value: v[0], left: None, right: None });\n    let mut q: Vec<usize> = Vec::new();\n    q.push(0);\n    let mut h = 0;\n    let mut i = 1;\n    while h < q.len() && i < v.len() {\n        let p = q[h];\n        h += 1;\n        for side in 0..2 {\n            if i < v.len() {\n                if v[i] != -1 {\n                    nodes.push(Node { value: v[i], left: None, right: None });\n                    let k = nodes.len() - 1;\n                    if side == 0 { nodes[p].left = Some(k); } else { nodes[p].right = Some(k); }\n                    q.push(k);\n                }\n                i += 1;\n            }\n        }\n    }\n    Tree { nodes: nodes, root: Some(0) }\n}\n\nfn to_tree(t: &Tree) -> Vec<i32> {\n    let mut out: Vec<i32> = Vec::new();\n    let mut q: Vec<Option<usize>> = Vec::new();\n    q.push(t.root);\n    let mut h = 0;\n    let mut seen = 0;\n    while h < q.len() && seen < t.nodes.len() {\n        let cur = q[h];\n        h += 1;\n        if let Some(i) = cur {\n            seen += 1;\n            out.push(t.nodes[i].value);\n            q.push(t.nodes[i].left);\n            q.push(t.nodes[i].right);\n        } else {\n            out.push(-1);\n        }\n    }\n    while out.len() > 0 && out[out.len() - 1] == -1 { out.pop(); }\n    out\n}\n\n'};

