     answer:'class Queue {\n  constructor() {\n    this.items = [];\n  }\n  enqueue(x) {\n    this.items.push(x);\n  }\n  dequeue() {\n    if (this.items.length === 0) {\n      return -1;\n    }\n    return this.items.shift();\n  }\n  front() {\n    if (this.items.length === 0) {\n      return -1;\n    }\n    return this.items[0];\n  }\n  isEmpty() {\n    return this.items.length === 0;\n  }\n  size() {\n    return this.items.length;\n  }\n}',
