     answer:'struct Queue {\n    items: Vec<i32>,\n}\n\nimpl Queue {\n    fn new() -> Queue {\n        Queue { items: Vec::new() }\n    }\n    fn enqueue(&mut self, x: i32) {\n        self.items.push(x);\n    }\n    fn dequeue(&mut self) -> i32 {\n        if self.items.len() == 0 {\n            return -1;\n        }\n        self.items.remove(0)\n    }\n    fn front(&self) -> i32 {\n        if self.items.len() == 0 {\n            return -1;\n        }\n        self.items[0]\n    }\n    fn is_empty(&self) -> bool {\n        self.items.len() == 0\n    }\n    fn size(&self) -> i32 {\n        self.items.len() as i32\n    }\n}',
