     answer:'struct Node {\n    value: i32,\n    next: Option<usize>,\n}\n\nstruct LinkedChain {\n    nodes: Vec<Node>,\n    head: Option<usize>,\n}\n\nimpl LinkedChain {\n    fn new() -> LinkedChain {\n        LinkedChain { nodes: Vec::new(), head: None }\n    }\n    fn add(&mut self, value: i32) {\n        self.nodes.push(Node { value: value, next: None });\n        let made = self.nodes.len() - 1;\n        match self.head {\n            None => {\n                self.head = Some(made);\n            }\n            Some(first) => {\n                let mut last = first;\n                let mut after = self.nodes[last].next;\n                while let Some(i) = after {\n                    last = i;\n                    after = self.nodes[last].next;\n                }\n                self.nodes[last].next = Some(made);\n            }\n        }\n    }\n    fn add_first(&mut self, value: i32) {\n        let old = self.head;\n        self.nodes.push(Node { value: value, next: old });\n        self.head = Some(self.nodes.len() - 1);\n    }\n    fn to_array(&self) -> Vec<i32> {\n        let mut out: Vec<i32> = Vec::new();\n        let mut cur = self.head;\n        while let Some(i) = cur {\n            out.push(self.nodes[i].value);\n            cur = self.nodes[i].next;\n        }\n        out\n    }\n}',
