     answer:'use std::collections::HashMap;\n\nfn lookup_all(keys: Vec<i32>, vals: Vec<i32>, queries: Vec<i32>) -> Vec<i32> {\n    let mut m: HashMap<i32, i32> = HashMap::new();\n    for i in 0..keys.len() {\n        m.insert(keys[i], vals[i]);\n    }\n    let mut out: Vec<i32> = Vec::new();\n    for q in queries.iter() {\n        match m.get(q) {\n            Some(v) => out.push(*v),\n            None => out.push(-1),\n        }\n    }\n    out\n}',
