     answer:TH.rs+'fn insert(mut t: Tree, value: i32) -> Tree {\n    let mut cur = match t.root {\n        Some(r) => r,\n        None => {\n            t.nodes.push(Node { value: value, left: None, right: None });\n            t.root = Some(t.nodes.len() - 1);\n            return t;\n        }\n    };\n    loop {\n        let here = t.nodes[cur].value;\n        let left = t.nodes[cur].left;\n        let right = t.nodes[cur].right;\n        if value == here {\n            return t;\n        }\n        if value < here {\n            if let Some(n) = left {\n                cur = n;\n            } else {\n                t.nodes.push(Node { value: value, left: None, right: None });\n                let k = t.nodes.len() - 1;\n                t.nodes[cur].left = Some(k);\n                return t;\n            }\n        } else {\n            if let Some(n) = right {\n                cur = n;\n            } else {\n                t.nodes.push(Node { value: value, left: None, right: None });\n                let k = t.nodes.len() - 1;\n                t.nodes[cur].right = Some(k);\n                return t;\n            }\n        }\n    }\n}',
